import{c as a,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Iterate","description":"","frontmatter":{},"headers":[{"level":1,"title":"Iterate","slug":"iterate"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Iterate.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Iterate.md"}'),n={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Iterate.md"};function r(i,t,d,o,p,h){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="iterate" tabindex="-1">Iterate <a class="header-anchor" href="#iterate" aria-label="Permalink to &quot;Iterate&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>每调用一次Iterate，会计算出一块baseM * baseN的C矩阵。接口内部会维护迭代进度，调用一次后会对A、B矩阵首地址进行偏移。默认以先M轴再N轴的迭代顺序，也可以通过调整tiling参数iterateOrder，转换为先N轴再M轴的迭代顺序。当传入数据未对齐，存在尾块时，会在最后一次迭代输出尾块的计算结果。</p><p>一次Iterate矩阵乘的结果C矩阵存放在逻辑位置CO1的内存中，对于CO1内存中计算结果的获取，当前支持如下两种方式：</p><ul><li>用户无需自行管理存放矩阵乘结果的CO1内存的申请和释放，由Matmul API内部实现管理。调用<a href="#li135771283591">接口内部管理CO1</a>的Iterate函数原型后，调用<a href="./GetTensorC.html">GetTensorC</a>接口完成CO1上计算结果的搬出。</li><li>用户可以灵活自主地控制矩阵乘计算结果的搬运，例如将多次Iterate计算的矩阵乘结果缓存在CO1内存中，在需要搬出该结果时，一次性搬出多块baseM * baseN的C矩阵。这种灵活搬运场景下，用户需要提前申请CO1的内存，调用<a href="#li4843165185812">用户自主管理CO1</a>的Iterate函数原型后，一次Iterate的计算结果会输出到用户申请的CO1内存上。在需要搬出计算结果时，调用<a href="./../../../基础API/矩阵计算（ISASI）/数据搬运/Fixpipe.html">Fixpipe</a>接口搬运CO1上的结果，完成后释放申请的CO1内存。具体示例请参考<a href="./Matmul使用说明.html#li12765161915318">用户自主管理CO1的矩阵乘场景</a>。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>接口内部管理CO1</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt; __aicore__ inline bool Iterate(bool enPartialSum = false)</span></span></code></pre></div></li><li><p>用户自主管理CO1</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true, typename T&gt; __aicore__ inline bool Iterate(bool enPartialSum, const LocalTensor&lt;T&gt;&amp; localCmatrix)</span></span></code></pre></div><ul><li>Atlas 推理系列产品AI Core暂不支持用户自主管理CO1。</li><li>Atlas 200I/500 A2 推理产品暂不支持用户自主管理CO1。</li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>迭代获取C矩阵分片的过程分为同步和异步两种模式。通过该参数设置同步或者异步模式：同步模式设置为true；异步模式设置为false。默认为同步模式。具体模式的介绍和使用方法请参考GetTensorC。</td></tr><tr><td>T</td><td>用户申请的CO1内存上LocalTensor的数据类型，即矩阵乘输出的C矩阵的数据类型。当前支持的数据类型为float、int32_t。</td></tr></tbody></table><p><strong>表 2</strong> 接口内部管理CO1的函数参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>enPartialSum</td><td>输入</td><td>是否将矩阵乘的结果累加于现有的CO1数据，默认值为false。在L0C累加时，只支持C矩阵规格为singleCoreM==baseM &amp;&amp; singleCoreN==baseN。 针对Atlas 200I/500 A2 推理产品，该参数仅支持配置为false。</td></tr></tbody></table><p><strong>表 3</strong> 用户自主管理CO1的函数参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>enPartialSum</td><td>输入</td><td>是否将矩阵乘的结果累加于现有的CO1数据。在L0C累加时，只支持C矩阵规格为singleCoreM==baseM &amp;&amp; singleCoreN==baseN。</td></tr><tr><td>localCmatrix</td><td>输出</td><td>由用户申请的CO1上的LocalTensor内存，用于存放矩阵乘的计算结果。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>false：单核上的所有数据全部算完。</p><p>true：数据仍在迭代计算中。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>当使能MixDualMaster（双主模式）场景时，即模板参数<a href="./MatmulConfig.html#p9218181073719">enableMixDualMaster</a>设置为true，不支持使用该接口。</li><li>对于用户自主管理CO1的Iterate函数，创建Matmul对象时，必须定义C矩阵的内存逻辑位置为TPosition::CO1、数据排布格式为CubeFormat::NZ、数据类型为float或int32_t。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>同步模式及异步模式的简单调用示例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 同步模式样例</span></span>
<span class="line"><span>while (mm.Iterate()) {   </span></span>
<span class="line"><span>    mm.GetTensorC(ubCmatrix); </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 异步模式样例</span></span>
<span class="line"><span>mm.template Iterate&lt;false&gt;();</span></span>
<span class="line"><span>// …… ……其它计算</span></span>
<span class="line"><span>for (int i = 0; i &lt; singleM/baseM*singleN/baseN; ++i) {   </span></span>
<span class="line"><span>    mm.template GetTensorC&lt;false&gt;(ubCmatrix); </span></span>
<span class="line"><span>}</span></span></code></pre></div>`,24)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
